Article "0..*" -- "1" FoodBank : dropped off at

Employee "1" -- "*" Article : examines
Employee "1" -- "*" Delivery : arranges

Client "1" -- "*" Delivery
Delivery "1" -- "1" Article
Delivery "1" -- "1" VolunteerDriver

@enduml

